 const keys=Object.keys(METRICS),fields=[{name:'longitude',type:'real'},{name:'latitude',type:'real'},{name:'elevation',type:'real'},{name:'parcel',type:'integer'},{name:'x',type:'integer'},{name:'y',type:'integer'},{name:'zone',type:'string'},{name:'level',type:'integer'},...keys.map(name=>({name,type:'real'}))];
