function setTool(value){ufoEvents?.cancel();endPaint();tool=value;view.followLaunch=false;view.cameraAltitude=0;hover=null;bridgeStart=null;document.querySelectorAll('.tool').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',String(b.dataset.tool===tool));});for(const d of document.querySelectorAll('#tools details')){const current=!!d.querySelector('[data-tool="'+tool+'"]'),summary=d.querySelector('summary');summary.classList.toggle('active',current);summary.innerHTML=icon(current?tool:summary.dataset.icon);summary.title=summary.getAttribute('aria-label')+(current?' · '+TOOLS[tool].name:'');}$('build-help').hidden=tool==='inspect';$('build-help').textContent=tool==='inspect'?'Inspect a parcel to see what it needs.':tool==='bridge'?'Choose two clear, aligned land endpoints.':`${TOOLS[tool].name} · hold left mouse + drag · ${money(TOOLS[tool].cost)}/parcel`;if(['pipe','wire','tunnel','drain'].includes(tool)){view.underground=true;view.network=tool;$('underground')?.classList.add('active');setOverlay(tool==='wire'?'power':tool==='pipe'?'water':tool==='tunnel'?'transit':'runoff');}else if(tool!=='inspect'&&!(tool==='bulldoze'&&$('demolition')?.value!=='surface')){view.underground=false;$('underground')?.classList.remove('active');}changed();}
function toolButton(name){
 const info=TOOLS[name],b=document.createElement('button');b.className='tool'+(name==='inspect'?' active':'');b.dataset.tool=name;b.style.setProperty('--tool-color',info.color||'#b4cbd7');b.title=info.name+(info.key?' ('+info.key+')':'')+(info.cost?' · '+money(info.cost):'');b.setAttribute('aria-label',info.name);b.setAttribute('aria-pressed',String(name==='inspect'));b.innerHTML=icon(name)+`<span class="tool-name">${info.name}</span>`;b.onclick=()=>{setTool(name);document.querySelectorAll('#tools details[open]').forEach(d=>d.open=false);};return b;
}
