const categories={Destinations:['commercial',['mall','stripmall','mixeduse','hotel','casino','bank','ferris']],Architecture:['skyscraper',['arcology','skyscraper','landmark','spaceport','port','airport','bridge']],Utilities:['power',['power','solar','hydrogen','dam','reservoir','pump','wire','pipe','drain']],Transport:['subway',['bus','subway','tunnel','elevated','elevatedStation','parking','garage','toll']],Services:['hospital',['school','hospital','police','fire']],Landscape:['park',['forest','wetland','flatten','raise','lower','reclaim']]};
