 const details=document.createElement('details'),summary=document.createElement('summary'),flyout=document.createElement('div');summary.title=label;summary.dataset.icon=shape;summary.setAttribute('aria-label',label);summary.innerHTML=icon(shape);flyout.className='tool-flyout';const heading=document.createElement('h3');heading.textContent=label;flyout.append(heading);for(const name of names)flyout.append(toolButton(name));details.append(summary,flyout);details.addEventListener('toggle',()=>{if(details.open){setPanel('build-options',false);for(const other of document.querySelectorAll('#tools details'))if(other!==details)other.open=false;}});$('tools').append(details);
