 if(tool==='bridge'){if(bridgeStart===null){bridgeStart=id;toast('First anchor selected. Choose the aligned far endpoint.');refresh({data:false,save:false});return;}checkpoint();const result=buildBridge(city,bridgeStart,id,view.bridge);bridgeStart=null;if(!result.ok)undoStack.pop();toast(result.message);refresh();return;}
