function setHover(id){if(hover===id&&lastHoverAggregate===hoverAggregate)return;hover=id;lastHoverAggregate=hoverAggregate;const t=city.tiles[id],el=$('hover-readout');if(el){el.hidden=!t||stroke!==null;if(t){const m=METRICS[overlay];el.textContent=hoverAggregate||`${t.x+1}, ${t.y+1} · ${TOOLS[t.type]?.name||t.terrain}${m?' · '+metricValue(city,t,overlay,analysis.snapshot).toLocaleString('en-US',{maximumFractionDigits:1})+' '+m.unit:''}`;}}if(!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=0;changed();});}
