function movePaint(id){if(!stroke)return;hover=id;const n=extendStroke(stroke,id);if(n){document.dispatchEvent(new CustomEvent('city-build-audio',{detail:tool}));city.activeTiles=city.tiles.filter(t=>t.type!=='empty'||t.pipe||t.wire||t.tunnel||t.drain||t.elevated);$('cash').textContent=money(city.cash);$('build-help').textContent=`${TOOLS[tool].name} · ${stroke.placed} parcels · ${money(stroke.cost)} · release to finish`;if(!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=0;changed();});}}
